// Package postgres implements the identity ports on PostgreSQL (schema
// "identity"), with queries generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/meepleo/meepleo-api/internal/identity/adapters/out/postgres/sqlcgen"
	"github.com/meepleo/meepleo-api/internal/identity/app"
	"github.com/meepleo/meepleo-api/internal/identity/domain"
	"github.com/meepleo/meepleo-api/internal/platform/postgres"
)

// Repository implements app.TxManager; the stores it hands out implement
// app.Users and app.RefreshTokens on the transaction.
type Repository struct {
	pool *pgxpool.Pool
	q    *sqlcgen.Queries
}

// NewRepository returns a Repository on pool.
func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool, q: sqlcgen.New(pool)}
}

// WithinTx implements app.TxManager.
func (r *Repository) WithinTx(ctx context.Context, fn func(context.Context, app.Users, app.RefreshTokens) error) error {
	return postgres.WithTx(ctx, r.pool, func(tx pgx.Tx) error {
		s := &store{q: r.q.WithTx(tx)}
		return fn(ctx, s, s)
	})
}

type store struct {
	q *sqlcgen.Queries
}

func (s *store) CreateGuest(ctx context.Context) (domain.User, error) {
	row, err := s.q.InsertUser(ctx, sqlcgen.IdentityUserKindGuest)
	if err != nil {
		return domain.User{}, fmt.Errorf("insert user: %w", err)
	}
	return domain.User{ID: domain.UserID(row.ID.String()), Kind: domain.UserKind(row.Kind), CreatedAt: row.CreatedAt.Time}, nil
}

func (s *store) Create(ctx context.Context, t app.NewRefreshToken) (domain.RefreshToken, error) {
	userID, err := parseUUID(string(t.UserID))
	if err != nil {
		return domain.RefreshToken{}, err
	}
	var family pgtype.UUID // NULL starts a new family
	if t.FamilyID != "" {
		if family, err = parseUUID(t.FamilyID); err != nil {
			return domain.RefreshToken{}, err
		}
	}
	row, err := s.q.InsertRefreshToken(ctx, sqlcgen.InsertRefreshTokenParams{
		UserID:    userID,
		FamilyID:  family,
		TokenHash: t.Hash,
		IssuedAt:  pgtype.Timestamptz{Time: t.IssuedAt, Valid: true},
		ExpiresAt: pgtype.Timestamptz{Time: t.ExpiresAt, Valid: true},
	})
	if err != nil {
		return domain.RefreshToken{}, fmt.Errorf("insert refresh token: %w", err)
	}
	return domain.RefreshToken{
		ID: row.ID.String(), UserID: t.UserID, FamilyID: row.FamilyID.String(), IssuedAt: t.IssuedAt, ExpiresAt: t.ExpiresAt,
	}, nil
}

func (s *store) ByHash(ctx context.Context, hash []byte) (domain.RefreshToken, error) {
	row, err := s.q.GetRefreshTokenByHash(ctx, hash)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.RefreshToken{}, domain.ErrInvalidRefreshToken
	}
	if err != nil {
		return domain.RefreshToken{}, fmt.Errorf("select refresh token: %w", err)
	}
	t := domain.RefreshToken{
		ID:        row.ID.String(),
		UserID:    domain.UserID(row.UserID.String()),
		FamilyID:  row.FamilyID.String(),
		IssuedAt:  row.IssuedAt.Time,
		ExpiresAt: row.ExpiresAt.Time,
	}
	if row.RevokedAt.Valid {
		t.RevokedAt = row.RevokedAt.Time
	}
	return t, nil
}

func (s *store) Revoke(ctx context.Context, id string, at time.Time) (bool, error) {
	uid, err := parseUUID(id)
	if err != nil {
		return false, err
	}
	n, err := s.q.RevokeRefreshToken(ctx, sqlcgen.RevokeRefreshTokenParams{ID: uid, RevokedAt: pgtype.Timestamptz{Time: at, Valid: true}})
	if err != nil {
		return false, fmt.Errorf("revoke refresh token: %w", err)
	}
	return n == 1, nil
}

func (s *store) RevokeFamily(ctx context.Context, familyID string, at time.Time) error {
	fid, err := parseUUID(familyID)
	if err != nil {
		return err
	}
	if err := s.q.RevokeFamily(ctx, sqlcgen.RevokeFamilyParams{FamilyID: fid, RevokedAt: pgtype.Timestamptz{Time: at, Valid: true}}); err != nil {
		return fmt.Errorf("revoke family: %w", err)
	}
	return nil
}

func (s *store) RevokeUser(ctx context.Context, userID domain.UserID, at time.Time) error {
	uid, err := parseUUID(string(userID))
	if err != nil {
		return err
	}
	if err := s.q.RevokeUserTokens(ctx, sqlcgen.RevokeUserTokensParams{UserID: uid, RevokedAt: pgtype.Timestamptz{Time: at, Valid: true}}); err != nil {
		return fmt.Errorf("revoke user tokens: %w", err)
	}
	return nil
}

func parseUUID(s string) (pgtype.UUID, error) {
	var u pgtype.UUID
	if err := u.Scan(s); err != nil {
		return u, fmt.Errorf("invalid uuid %q: %w", s, err)
	}
	return u, nil
}
